css:
body{font-family:Arial,sans-serif;font-size:13px;color:#1a1a1a}
.pa-wrap{max-width:820px;margin:0 auto}
.stmt-header{text-align:center;border-bottom:3px solid #2c5f2e;padding-bottom:12px;margin-bottom:20px}
.stmt-header h1{margin:0;font-size:22px;color:#2c5f2e;letter-spacing:2px}
.stmt-header h2{margin:4px 0 0;font-size:12px;font-weight:normal;color:#555}
.stmt-title{text-align:center;margin:0 0 20px}
.stmt-title span{font-size:16px;font-weight:bold;letter-spacing:3px;border:2px solid #2c5f2e;padding:4px 18px;color:#2c5f2e}
.status-box{text-align:center;padding:10px;margin:0 0 22px;border-radius:4px;border:2px solid #ddd}
.status-box .status-label{font-size:11px;text-transform:uppercase;color:#666;letter-spacing:.8px}
.status-box .status-value{display:block;font-size:20px;font-weight:bold;letter-spacing:2px;margin-top:4px}
.status-submitted,.status-draft{background:#e2e3e5;border-color:#adb5bd;color:#383d41}
.status-paid{background:#d4edda;border-color:#28a745;color:#155724}
.status-expired,.status-cancelled{background:#f8d7da;border-color:#dc3545;color:#721c24}
.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin-bottom:20px}
.meta-block h4{margin:0 0 6px;font-size:10px;text-transform:uppercase;color:#888;border-bottom:1px solid #ddd;padding-bottom:3px}
.meta-block p{margin:3px 0;font-size:13px}
.meta-block .lbl{color:#666;font-size:11px}
.section-title{font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.8px;border-bottom:2px solid #2c5f2e;padding-bottom:4px;margin:22px 0 10px;color:#2c5f2e}
table.fee-table,table.validity-table,table.links-table{width:100%;border-collapse:collapse;margin-bottom:16px}
table.fee-table td,table.validity-table td,table.links-table td{padding:8px 10px;font-size:13px;border-bottom:1px solid #eee}
.fee-lbl,.lnk-lbl{background:#f0f7f0;font-weight:bold;font-size:11px;width:20%;color:#2c5f2e;white-space:nowrap}
.fee-val{width:30%;font-weight:bold;font-size:14px}
.badge{display:inline-block;padding:2px 10px;border-radius:10px;font-size:11px;font-weight:bold}
.bg-paid{background:#d4edda;color:#155724}
.bg-pending{background:#e2e3e5;color:#383d41}
.bg-overdue{background:#f8d7da;color:#721c24}
.notice-box{background:#f0f7f0;border-left:4px solid #2c5f2e;padding:10px 14px;margin:20px 0;font-size:12px;color:#333}
.footer{border-top:1px solid #ddd;padding-top:10px;margin-top:20px;font-size:11px;color:#888;text-align:center}
